c3='''def modes(counts):
    greatest = counts[0]
    for count in counts:
        if count > greatest:
            greatest = count
    result = []
    for value in range(len(counts)):
        if counts[value] == greatest:
            result.append(value)
    return result'''
add('15:c',['B2.2.2','B2.3.2','B2.3.3'],'Construct modes(counts) in Python. counts is a nonempty list of digit frequencies with at least one positive count. Return every digit tied for the greatest frequency. To assess the search, do not call max or sorted.','One solution:\n'+c3,[(1,'Initializes greatest from valid count.'),(1,'Traverses counts to find greatest.'),(1,'Correct comparison/update.'),(1,'Examines all candidate digit indices.'),(1,'Selects every count equal to greatest.'),(1,'Returns digit values and handles ties.')],[17,18],status='B',new_command='Construct',code=c3,context_pages=[7,8],check='Executed unique mode, tie and all equal frequency cases.',test_code=c3+'\nassert modes([2,5,5,0])==[1,2]\nassert modes([0,4,1])==[1]\nassert modes([3,3,3])==[0,1,2]')
